import XCTest
import CheckmateCore
@testable import CheckmateDomain
@testable import CheckmateSupport
@testable import CheckmateRules
@testable import CheckmateEngine
@testable import CheckmateContent
@testable import CheckmateApplication
@testable import CheckmateMacPlatform

@MainActor final class OpponentCalibrationTests:XCTestCase {
    private func claimsDraw(_ rules:ChessRules)->Bool {
        let key={ (fen:String) in fen.split(separator:" ").prefix(4).joined(separator:" ") }
        let positions=[rules.records.first?.before ?? rules.fen]+rules.records.map(\.after)
        return (Int(rules.fen.split(separator:" ")[4]) ?? 0)>=100 || positions.filter{key($0)==key(rules.fen)}.count>=3
    }
    func testSeededCompleteGames()async throws {
        guard let raw=ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_GAMES"],let games=Int(raw),games>=100,let directory=ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_DIR"] else{throw XCTSkip("Explicit build-host long calibration gate; >=100 games/profile.")}
        let openings=[[String](),["e2e4","e7e5"],["d2d4","d7d5"],["g1f3","g8f6"],["c2c4","e7e5"]],engine=NativeEngine();var report:[[String:Any]]=[]
        var profiles=[OpponentProfile.beginner,.skill(0),.skill(10)];if ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_ELO"]=="1"{profiles.append(.elo(1320))};if ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_ONLY"]=="elo"{profiles=[.elo(1320)]};if ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_ONLY"]=="beginner"{profiles=[.beginner]};if ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_ONLY"]=="skill0"{profiles=[.skill(0)]};if ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_ONLY"]=="skill10"{profiles=[.skill(10)]}
        for profile in profiles {var completed=0,claimedDraws=0,unfinished=0,illegal=0,wins=0,draws=0,losses=0,mateExposure=0,totalPlies=0,maximumEstimatedSevereStreak=0,fallbackChoices=0,decisionSamples=0,unknownDecisionRegrets=0,decisionRegrets:[Int]=[],times:[Double]=[],regrets:[Int]=[]
            for index in 0..<games {let rules=try ChessRules();for move in openings[index%openings.count]{try rules.move(uci:move)};let candidateSide=index%2==0 ? "w":"b";var outcome="",severeStreak=0,uncappedStreak=0
                while !rules.over && !claimsDraw(rules) && rules.history.count<250 {let start=Date(),candidate=rules.turn==candidateSide,result:EngineAnalysis
                    if candidate && profile.mode=="beginner"{result=try await BeginnerOpponent.choose(rules:rules,engine:engine,seed:UInt64(index*1000+rules.history.count+1),severeStreak:severeStreak)}else{result=try await engine.analyzeHistory(startFEN:rules.records.first?.before ?? rules.fen,moves:rules.records.map(\.uci),profile:candidate ? profile:.skill(20),budget:100,multiPv:1)}
                    if candidate && profile.mode=="beginner" {if let decision=result.opponentDecision{decisionSamples+=1;XCTAssertEqual(decision.policyVersion,BeginnerPolicy.version);XCTAssertEqual(decision.priorSevereStreak,severeStreak);if decision.fallback{fallbackChoices+=1};if let regret=decision.estimatedRegretCp{decisionRegrets.append(regret)}else{unknownDecisionRegrets+=1}};let best=result.lines.first?.score,chosen=result.lines.first(where:{$0.pv.first==result.bestMove})?.score;if let best=best,let chosen=chosen,best.kind=="cp",chosen.kind=="cp",best.bound==nil,chosen.bound==nil,max(0,(best.value-chosen.value)*(rules.turn=="w" ? 1:-1))>=BeginnerPolicy.severeRegretCp{uncappedStreak+=1}else{uncappedStreak=0};maximumEstimatedSevereStreak=max(maximumEstimatedSevereStreak,uncappedStreak);severeStreak=BeginnerOpponent.nextSevereStreak(result,mover:rules.turn,current:severeStreak)}
                    if candidate {times.append(Date().timeIntervalSince(start)*1000)
                        if let selected=result.bestMove {let startFEN=rules.records.first?.before ?? rules.fen,history=rules.records.map(\.uci);let reference=try await engine.analyzeHistory(startFEN:startFEN,moves:history,profile:.skill(20),budget:100,multiPv:3),actual=try await engine.analyzeHistory(startFEN:startFEN,moves:history,profile:.skill(20),budget:100,multiPv:1,searchMoves:[selected]);if let best=reference.lines.first?.score,let played=actual.lines.first?.score,best.kind=="cp",played.kind=="cp",best.bound==nil,played.bound==nil{regrets.append(max(0,(best.value-played.value)*(candidateSide=="w" ? 1:-1)))};if actual.lines.first?.score.kind=="mate",(actual.lines.first?.score.value ?? 0)*(candidateSide=="w" ? 1:-1)<0{mateExposure+=1}}
                    }
                    guard let move=result.bestMove,rules.moves().contains(where:{$0.uci==move}) else{illegal+=1;break};try rules.move(uci:move)
                }
                let archive=URL(fileURLWithPath:directory).appendingPathComponent("games-\(profile.mode)-\(profile.value)");try FileManager.default.createDirectory(at:archive,withIntermediateDirectories:true);try Data(rules.pgn.utf8).write(to:archive.appendingPathComponent(String(format:"%03d.pgn",index+1)),options:.atomic)
                totalPlies+=rules.history.count
                // A ply-cap stop is unfinished (*): neither a rules draw nor a player agreement.
                if rules.checkmate{outcome=rules.turn==candidateSide ? "loss":"win";completed+=1}else if rules.over || claimsDraw(rules){outcome="draw";completed+=1;if !rules.over{claimedDraws+=1}}else{outcome="unfinished";unfinished+=1}
                if outcome=="win"{wins+=1}else if outcome=="loss"{losses+=1}else if outcome=="draw"{draws+=1}
                let progress:[String:Any]=["profile":jsonObject(profile),"games":index+1,"terminalGames":completed-claimedDraws,"claimedDraws":claimedDraws,"completedGames":completed,"unfinishedAtPlyCap":unfinished,"capsCountAsDraw":false];try JSONSerialization.data(withJSONObject:progress,options:.prettyPrinted).write(to:URL(fileURLWithPath:directory+"/calibration-progress.json"),options:.atomic)
            }
            times.sort();regrets.sort();decisionRegrets.sort();let row:[String:Any]=["profile":jsonObject(profile),"opponentProfileSchemaVersion":profile.version,"beginnerPolicy":profile.mode=="beginner" ? ["version":BeginnerPolicy.version,"severeRegretCp":BeginnerPolicy.severeRegretCp,"maximumConsecutiveSevereErrors":BeginnerPolicy.maximumConsecutiveSevereErrors,"maximumRegretCp":BeginnerPolicy.maximumRegretCp,"minorRegretCp":BeginnerPolicy.minorRegretCp,"candidateCount":BeginnerPolicy.candidateCount,"explorationCount":BeginnerPolicy.explorationCount,"budgetMs":BeginnerPolicy.budgetMs,"mistakePercent":BeginnerPolicy.mistakePercent] as Any:NSNull(),"sourceHashManifest":"source-sha256.txt","games":games,"terminalGames":completed-claimedDraws,"claimedDraws":claimedDraws,"completedGames":completed,"unfinishedAtPlyCap":unfinished,"capsCountAsDraw":false,"claimPolicy":"Either side always claims an eligible threefold/fifty-move draw in this self-play experiment; claimed draws are distinct from terminal positions.","maximumPlies":250,"whiteGames":games/2,"blackGames":games/2,"illegalMoves":illegal,"wins":wins,"draws":draws,"losses":losses,"totalPlies":totalPlies,"mateExposureSamples":mateExposure,"maximumPolicyEstimatedSevereStreak":maximumEstimatedSevereStreak,"policyDecisionSamples":decisionSamples,"policyFallbackChoices":fallbackChoices,"policyUnknownDecisionRegrets":unknownDecisionRegrets,"policyEstimatedRegretP50Cp":decisionRegrets.isEmpty ? 0:decisionRegrets[decisionRegrets.count/2],"policyEstimatedRegretP95Cp":decisionRegrets.isEmpty ? 0:decisionRegrets[min(decisionRegrets.count-1,Int(Double(decisionRegrets.count)*0.95))],"regretMethod":"Independent full-strength root versus searchmoves chosen move, matched100ms/explicit node-tier; cp-only exact non-bound samples","regretSamples":regrets.count,"regretP50Cp":regrets.isEmpty ? 0:regrets[regrets.count/2],"regretP95Cp":regrets.isEmpty ? 0:regrets[min(regrets.count-1,Int(Double(regrets.count)*0.95))],"responseP50Ms":times[times.count/2],"responseP95Ms":times[min(times.count-1,Int(Double(times.count)*0.95))],"engine":engine.capabilities.name,"engineHash":engine.binaryIdentity,"searchNodes":ProcessInfo.processInfo.environment["CHECKMATE_CALIBRATION_NODES"] ?? "production movetime","limitation":"Node-budget calibration tier differs from production latency; games stopped at the 250-ply cap are unfinished (*), reported separately, and are neither completed games nor draws. No human Elo claim. Novice acceptance pending."]
            report.append(row);try JSONSerialization.data(withJSONObject:report,options:[.prettyPrinted,.sortedKeys]).write(to:URL(fileURLWithPath:directory+"/opponent-calibration.json"),options:.atomic);XCTAssertEqual(illegal,0);if profile.mode=="beginner"{XCTAssertLessThanOrEqual(maximumEstimatedSevereStreak,BeginnerPolicy.maximumConsecutiveSevereErrors)}
        }
    }
}
